insert into public.idle_cat_conquista (id, nome, frase, condicao, tipo, alvo, valor, escondida) values
  (1, 'Cem abas abertas', 'Cem abas, zero vagas aplicadas. Seu pai já desistiu de você em silêncio.', 'Ter 100 "Você, no notebook da faculdade"', 'gerador', 1, 100, false),
  (2, 'Guru do LinkedIn', 'Escreveu "fui demitido e isso me ensinou" cem vezes. Ninguém te recontratou.', 'Ter 100 "Post motivacional no LinkedIn"', 'gerador', 2, 100, false),
  (3, 'PROCV emocional', 'Cruza dez mil linhas no Excel e não consegue cruzar a rua pra ir na terapia.', 'Ter 100 "Planilha no Excel"', 'gerador', 3, 100, false),
  (4, 'Pirâmide familiar', 'Vendeu pra família toda. Agora o Natal é por videochamada e a tia não atende.', 'Ter 100 "Vendendo pra tia no grupo da família"', 'gerador', 4, 100, false),
  (5, 'CLT jamais', 'Cem clientes, zero férias, um burnout e nenhum INSS pra pagar o remédio.', 'Ter 100 "Freela no Fiverr"', 'gerador', 5, 100, false),
  (6, 'Live pra três pessoas', 'Cem horas ao vivo pra sua mãe, um bot e um cara que só pede pé.', 'Ter 100 "Live na Twitch"', 'gerador', 6, 100, false),
  (7, 'Estágio não remunerado em escala', 'Cem estagiários pagos em "experiência". A princesa Isabel ficaria decepcionada.', 'Ter 100 "Estagiário"', 'gerador', 7, 100, false),
  (8, 'Fábrica de chaveiro', 'Cem impressoras derretendo plástico. Seus pulmões vão entrar no grupo do processo.', 'Ter 100 "Impressora 3D"', 'gerador', 8, 100, false),
  (9, 'Rei do zap', 'Cem grupos de zap. Você é o motivo de inventarem o "silenciar por 1 ano".', 'Ter 100 "Grupo de vendas no zap"', 'gerador', 9, 100, false),
  (10, 'Chega em 40 dias', 'Revende lixo chinês com 400% de margem e chama de empreendedorismo. O Procon chama de outra coisa.', 'Ter 100 "Dropshipping"', 'gerador', 10, 100, false),
  (11, 'Frota de food truck', 'Hambúrguer de F$ 49 com carne de origem desconhecida. A Vigilância Sanitária ainda não achou você.', 'Ter 100 "Food truck"', 'gerador', 11, 100, false),
  (12, 'MercadoLíder Platinum', 'Cem lojas, mil reclamações, nenhum produto chegou inteiro.', 'Ter 100 "Loja no Mercado Livre"', 'gerador', 12, 100, false),
  (13, 'Cem episódios', 'Três homens sem terapia falando de investimento por cem episódios.', 'Ter 100 "PPP Podcast"', 'gerador', 13, 100, false),
  (14, 'Agência de influencer', 'Cem influencers vendendo chá emagrecedor pra menor de idade. Que orgulho.', 'Ter 100 "Influencer parceiro"', 'gerador', 14, 100, false),
  (15, 'Tem um app pra isso', 'Cem apps pedindo sua localização, seus contatos e sua alma.', 'Ter 100 "App na App Store"', 'gerador', 15, 100, false),
